  "criteria": [
    {
      "question": "回答是否采用了标准的剧本格式（包含场景描述、角色名及对应的对话/动作指令），且明确标注为 Day 1？",
      "weight": 0.25
    },
    {
      "question": "剧本是否完整包含了任务指定的核心情节链条：从回顾合影开始，到遭遇 Enderiophages，发现 Androphage 异常生病，最后揭示其腹中幼虫并推断末影人消失？",
      "weight": 0.35
    },
    {
      "question": "对于‘查看照片’这一前置背景，回答是否通过具体的感官描写（如看着照片时的神态、回忆的语气）赋予了情感色彩，从而自然引出后续面对恐怖景象的反差，而非仅用一句话机械带过？",
      "weight": 0.20
    },
    {
      "question": "Androphage 的角色表现是否体现了其‘对末影人有侵略性但此刻显得病态’的矛盾特征，且 [player] 的反应符合其作为观察者与救助者的身份？",
      "weight": 0.20
    }
  ]
}

{
  "criterion_judgments": [
    {
      "criterion_id": "1",
      "satisfied": true,
      "reason": "回答中包含'Master'和'Student'两个角色，并以对话形式呈现了至少三段交流内容。"
    },
    {
      "criterion_id": "2",
      "satisfied": true,
      "reason": "对话引用了著名的禅宗公案（单手拍掌声），并围绕‘真实本性’、‘超越概念与语言’等禅宗核心主题展开讨论。"
    },
    {
      "criterion_id": "3",
      "satisfied": false,
      "reason": "虽然对话本身包含反问（公案问题）和陈述，但整体回答中角色的语言风格较为单一，且随后的解释部分完全由AI以说教口吻进行定义，未能通过对话本身充分展示幽默、隐喻等多维度的思想侧面，更多是直白的概念阐述而非多样化的风格呈现。"
    }
  ]
}

